async def build_report(case_id: str) -> None:
    pdf = render_pdf(case_id)  # blocks the thread for 3 s
    send_email(case_id, pdf)

@app.post("/cases/{case_id}/report", status_code=202)
async def request_report(
    case_id: str, background: BackgroundTasks
) -> dict:
    background.add_task(build_report, case_id)
    return {"status": "accepted"}
